<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/branch-team.php';require_once __DIR__.'/../includes/stock-branches.php';
function check($ok,$message){if(!$ok)throw new RuntimeException($message);}function denied($work,$status){try{$work();}catch(CatalogException $e){check($e->status===$status,$e->getMessage());return;}throw new RuntimeException('Expected '.$status);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);initialize_database($db);
foreach(['Owner','Member','Other']as$i=>$name)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash,role) VALUES(?,?,?,?,?)',[$name,$name,'security'.$i.'@example.invalid','unused',$i===0?'manager':'usuario']);
$b=branch_save($db,1,['name'=>'Branch','address'=>'A','locality'=>'B','province'=>'C'])['branch'];$branch=(int)$b['id'];$workspace=(int)stock_query($db,'INSERT INTO branch_workspaces(owner_id,name) VALUES(1,?) RETURNING id',['Team'])->fetchColumn();team_attach($db,1,$workspace,$branch);
$geo=['latitude'=>10,'longitude'=>20,'accuracy'=>10,'position_at'=>time()];denied(fn()=>team_require_position($db,$branch,$geo),409);
team_security_save($db,1,$branch,['latitude'=>10,'longitude'=>20,'radius'=>200,'revision'=>0]);denied(fn()=>team_security_save($db,1,$branch,['latitude'=>10,'longitude'=>20,'radius'=>500,'revision'=>0]),409);
$token=team_invite($db,1,$branch,'operator','',false,25200);$hash=hash('sha256',$token);
denied(fn()=>team_accept($db,2,$token),422);denied(fn()=>team_accept($db,2,$token,array_replace($geo,['latitude'=>11])),403);denied(fn()=>team_accept($db,2,$token,array_replace($geo,['accuracy'=>500])),422);denied(fn()=>team_accept($db,2,$token,array_replace($geo,['position_at'=>time()-90])),422);
check(stock_query($db,'SELECT used_by FROM branch_team_invites WHERE token_hash=?',[$hash])->fetchColumn()===null,'geo failure does not consume token');
team_accept($db,2,$token,$geo);$expiry=(int)stock_query($db,'SELECT expires_at FROM branch_team_members WHERE user_id=2')->fetchColumn();check(abs($expiry-time()-25200)<=1,'7 hours starts on acceptance');denied(fn()=>team_accept($db,3,$token,$geo),410);denied(fn()=>team_security_save($db,2,$branch,['latitude'=>10,'longitude'=>20,'radius'=>200,'revision'=>1]),403);
stock_query($db,'INSERT INTO pallet_labels(code,reserved_by,reserved_until) VALUES(?,3,?)',['11223344',time()+3600]);$p=stock_claim($db,'11223344',3);$pallet=(int)stock_query($db,'SELECT id FROM pallets WHERE code=?',['11223344'])->fetchColumn();
denied(fn()=>team_scan($db,2,'11223344',$branch,array_replace($geo,['longitude'=>21])),403);check(stock_query($db,'SELECT branch_id FROM pallets WHERE id=?',[$pallet])->fetchColumn()===null,'blocked scan does not assign');team_scan($db,2,'11223344',$branch,$geo);stock_editable($db,$pallet,2);
$watch=stock_watch($db,'11223344',2,null);stock_query($db,'UPDATE branch_team_members SET expires_at=? WHERE user_id=2',[time()-1]);check(team_role($db,2,$branch)==='','expired role');check(team_locations($db,2)===[],'expired location hidden');denied(fn()=>stock_editable($db,$pallet,2),403);check(!stock_watch($db,'11223344',2,$watch['watch_stamp'])['unchanged'],'watch detects expiry');check(!stock_detail($db,'11223344',2)['can_edit'],'stock detail expires');stock_editable($db,$pallet,3);
$next=team_invite($db,1,$branch,'operator','security1@example.invalid',true);team_accept($db,2,$next,$geo);check(stock_query($db,'SELECT expires_at FROM branch_team_members WHERE user_id=2')->fetchColumn()===null,'permanent option has no expiry');
$foreign=branch_save($db,1,['name'=>'Elsewhere','address'=>'D','locality'=>'E','province'=>'F'])['branch'];stock_query($db,'UPDATE pallets SET branch_id=? WHERE id=?',[$foreign['id'],$pallet]);team_scan($db,2,'11223344',$branch,$geo);check((int)stock_query($db,'SELECT branch_id FROM pallets WHERE id=?',[$pallet])->fetchColumn()===$branch,'verified selected branch replaces old branch');
echo "OK: location configured/revision/roles, missing/far/imprecise/stale, no mutation or token consumption on denial, single use, 7h from accept, stock/edit/watch expiry, independent owner, permanent renewal and located reassignment.\n";

$revision=team_security($db,$branch)['revision'];team_security_save($db,1,$branch,['enabled'=>'0','default_seconds'=>'14400','latitude'=>10,'longitude'=>20,'radius'=>200,'revision'=>$revision]);check(team_security($db,$branch)['enabled']===0,'admin disables location');check((int)team_security($db,$branch)['default_seconds']===14400,'default duration');team_scan($db,2,'11223344',$branch,[]);stock_query($db,'UPDATE branch_team_members SET active=0 WHERE user_id=2');foreach([3600,14400,25200,43200,null] as $seconds){$t=team_invite($db,1,$branch,'operator','',false,$seconds);team_accept($db,2,$t,[]);$actual=stock_query($db,'SELECT expires_at FROM branch_team_members WHERE user_id=2')->fetchColumn();check($seconds===null?$actual===null:abs((int)$actual-time()-$seconds)<=1,'duration option');stock_query($db,'UPDATE branch_team_members SET active=0 WHERE user_id=2');}echo "OK: admin security toggle, no-location acceptance/scan when disabled and all durations.\n";

$mapBranch=branch_save($db,1,['name'=>'Located','address'=>'A2','locality'=>'B2','province'=>'C2','latitude'=>-34.6,'longitude'=>-58.4])['branch'];$site=team_security($db,(int)$mapBranch['id']);check(abs((float)$site['latitude']+34.6)<.00001&&abs((float)$site['longitude']+58.4)<.00001,'uses linked directory point by default');echo "OK: directory point fallback.\n";
